// SCRATCH PROBE — measures the host_agent_wiring telemetry fixture's request
// estimate. Deleted before finalizing; not part of the deliverable.
import 'dart:typed_data';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

void main() {
  test('probe: request estimate at the 8192 fixture window', () {
    final env = MemoryExecutionEnv(cwd: '/w');
    final wired = wireAgentCore(
      profile: cliProfile,
      services: AgentCoreServices(env: env, envRead: (name) => null),
    );
    final stack = wired.buildAgentStack(
      spec: AgentWiringSpec(
        model: const Model(
          id: 'kimi-k2',
          api: 'openai-completions',
          provider: 'kimi',
          baseUrl: 'https://api.kimi.com',
          contextWindow: 8192,
          maxTokens: 1024,
        ),
        systemPrompt: 's',
      ),
      streamFunction: (model, context, {cancelToken}) =>
          AssistantMessageEventStream(),
    );
    final tools = stack.agent.state.tools;
    final tokens = estimateRequestTokens(
      [UserMessage.text('hi')],
      systemPrompt: 's',
      tools: tools,
    );
    print('PROBE tools=${tools.length} tokens=$tokens window=8192 over=${tokens - 8192}');
    // Per-tool description cost of the bash tool.
    final bash = tools.firstWhere((t) => t.name == 'bash');
    final est =
        estimateRequestTokens(const [], systemPrompt: bash.description);
    print('PROBE bashDescriptionChars=${bash.description.length} bashEst=$est');
    for (final t in tools) {
      final e = estimateRequestTokens(const [], systemPrompt: t.description);
      print('PROBE tool=${t.name} est=$e chars=${t.description.length}');
    }
  });
}

